        console.log('T-lock-ident. Testing process snapshot + isExpectedMcpProcess ...');
        {
            const lock = require(path.join(CLI_DIR, 'memory-index-lock.js'));

            // ── availability block ────────────────────────────────────────
            // [memory-lock-win-cim-snapshot-reliability] Phase 3A Task 5 (E3).
            //
            // This block talks to the real machine, so it is the ONLY place that
            // tolerates anything — and it tolerates exactly one thing: the
            // external query not answering within its budget. Every other
            // unavailable reason means the command, the transport or the
            // contract is wrong, and still fails.
            //
            // The tolerance stops here. The deterministic safety block below is
            // seam-injected, always runs, and never bends.
            const selfResult = lock.getProcessSnapshotResult(process.pid);
            let self = null;
            if (selfResult.state === 'unavailable' && selfResult.reason === 'timeout') {
                // The external Windows query has a first-invocation latency tail
                // that sometimes exceeds the 10s budget. That is a runner
                // availability event, not a defect in this code — but it must be
                // evidenced, never silently swallowed.
                try {
                    const diag = require(path.join(WORKSPACE_ROOT, 'scripts', 'diagnostics', 'memory-lock-cim-snapshot.js'));
                    diag.emitLine(diag.collect({ label: 'T-lock-ident-timeout' }));
                } catch (err) {
                    // Same data boundary as the diagnostic itself: a require or
                    // spawn failure message can carry paths and arguments, so it
                    // goes through the production sanitizer before it is logged.
                    console.log(`CIM_SNAPSHOT_DIAG_ERROR=${JSON.stringify({ message: lock.safeStreamSample(String(err && err.message)) })}`);
                }
                console.log(`   ⏭️  external snapshot query timed out (${selfResult.detail.elapsedMs}ms of ${selfResult.detail.timeoutMs}ms) — availability event, evidence above`);
            } else {
                assert.strictEqual(selfResult.state, 'alive',
                    `self snapshot must be alive; only unavailable/timeout is tolerated, got ${selfResult.state}/${selfResult.reason || '-'}`);
                self = selfResult.snapshot;
                assert.ok(self && self.alive === true, 'self snapshot alive');
                assert.strictEqual(self.isNode, true, 'self is a node process');
                assert.ok(typeof self.commandLine === 'string' && self.commandLine.length > 0, 'commandLine captured');
                assert.ok(self.startedAt && !Number.isNaN(Date.parse(self.startedAt)), 'startedAt is a valid time');
                assert.ok(Number.isInteger(self.ppid), 'ppid captured');

                // 自报 startedAt(uptime 推导)与系统实测在容差内一致
                const drift = Math.abs(Date.parse(lock.selfStartedAt()) - Date.parse(self.startedAt));
                assert.ok(drift <= 5000, `selfStartedAt drift ${drift}ms exceeds 5s`);
            }

            // ── deterministic safety block ────────────────────────────────
            // Runs whatever the real machine did. A timed-out query must still
            // map to unknown / report-only and must never authorise a kill.
            {
                const injected = lock.getProcessSnapshotResult(process.pid, {
                    snapshotFn: () => ({ state: 'unavailable', reason: 'timeout', detail: {} }),
                });
                assert.strictEqual(injected.state, 'unavailable', 'a timed-out query is unavailable, deterministically');
                assert.strictEqual(lock.getProcessSnapshot(process.pid, {
                    snapshotFn: () => ({ state: 'unavailable', reason: 'timeout', detail: {} }),
                }), null, 'the compatibility surface still reports null for an unavailable query');
            }

            // 已死 pid → alive:false
            const deadChild = childProcess.spawnSync(process.execPath, ['-e', 'process.exit(0)']);
            const deadSnap = lock.getProcessSnapshot(deadChild.pid);
            assert.ok(deadSnap && deadSnap.alive === false, 'dead pid reports alive:false');

            // seam:注入失败 → null(调用方按不可确认处理)
            assert.strictEqual(lock.getProcessSnapshot(1, { snapshotFn: () => { throw new Error('denied'); } }), null);

            // quote-aware tokenizer(plan R1 P0-3):带空格路径不得被拆碎
            assert.deepStrictEqual(
                lock.commandTokens('node "C:\\tmp path\\x\\memory.js" mcp'),
                ['node', 'C:\\tmp path\\x\\memory.js', 'mcp']);
            assert.deepStrictEqual(
                lock.commandTokens("node '/tmp/my dir/memory.js' mcp"),
                ['node', '/tmp/my dir/memory.js', 'mcp']);
            assert.deepStrictEqual(
                lock.commandTokens('node C:/plain/memory.js stats'),
                ['node', 'C:/plain/memory.js', 'stats']);

            // isExpectedMcpProcess:entrypoint 归一化精确等值(禁止 suffix 匹配),
            // 命令 token 必须是 mcp,startedAt 必须存在且吻合
            const owner = { entrypoint: 'C:/tmp path/x/memory.js', processStartedAt: '2026-07-23T08:00:00.000Z' };
            const snapOf = cmd => ({ alive: true, isNode: true, commandLine: cmd, ppid: 1, ppidAlive: false, startedAt: '2026-07-23T08:00:01.000Z' });
            assert.strictEqual(lock.isExpectedMcpProcess(snapOf('node "C:\\tmp path\\x\\memory.js" mcp'), owner), true, 'quoted spaced path, exact match, accepted');
            assert.strictEqual(lock.isExpectedMcpProcess(snapOf('node "C:\\other path\\x\\memory.js" mcp'), owner), false, 'different path rejected');
            assert.strictEqual(lock.isExpectedMcpProcess(snapOf('node "C:\\tmp path\\x\\memory.js" stats'), owner), false, 'stats must NOT pass');
            assert.strictEqual(lock.isExpectedMcpProcess(snapOf('node "C:\\tmp path\\x\\memory.js" rebuild'), owner), false, 'rebuild must NOT pass');
            assert.strictEqual(lock.isExpectedMcpProcess(snapOf('node "C:\\tmp path\\x\\memory.js" mcp-extra'), owner), false, 'mcp-extra is not the mcp token');
            assert.strictEqual(lock.isExpectedMcpProcess(snapOf('node "C:\\x\\memory.js" mcp'), owner), false, 'suffix-only overlap rejected (exact equality required)');
            const plainOwner = { entrypoint: 'C:/tmp/x/memory.js', processStartedAt: '2026-07-23T08:00:00.000Z' };
            assert.strictEqual(lock.isExpectedMcpProcess(snapOf('node C:\\tmp\\x\\memory.js mcp'), plainOwner), true, 'backslash path normalized to exact match');
            assert.strictEqual(lock.isExpectedMcpProcess({ ...snapOf('node C:/tmp/x/memory.js mcp'), startedAt: '2026-07-23T09:00:00.000Z' }, plainOwner), false, 'startedAt mismatch = PID reuse, rejected');
            assert.strictEqual(lock.isExpectedMcpProcess(snapOf('node C:/tmp/x/memory.js mcp'), { entrypoint: 'C:/tmp/x/memory.js' }), false, 'missing processStartedAt = gate fails, not skipped');
            assert.strictEqual(lock.isExpectedMcpProcess({ ...snapOf('node C:/tmp/x/memory.js mcp'), isNode: false }, plainOwner), false, 'non-node rejected');
            assert.strictEqual(lock.isExpectedMcpProcess(null, plainOwner), false);
            assert.strictEqual(lock.isExpectedMcpProcess(snapOf('node C:/tmp/x/memory.js mcp'), null), false);
        }
        console.log('✅ T-lock-ident passed');

        // [memory-lock-win-cim-snapshot-reliability] Phase 3A Task 1 —
        // getProcessSnapshot folds six distinct events into one null, so a slow
        // runner and a broken command are indistinguishable to the caller and to
        // the gate. These cases pin the structured classification.
        //
        // Everything is produced through the execFileSyncFn seam, which carries
        // the NATIVE contract: stdout on success, throw on failure. The
        // classifier never sees a real PowerShell.
        console.log('T-snap-classify. Structured snapshot classification — nine outcomes, seam-injected ...');
        {
            const lock = require(path.join(CLI_DIR, 'memory-index-lock.js'));
            const WIN = process.platform === 'win32';

            // Platform-appropriate fixtures. The parse layer differs (JSON on
            // win32, `ps` text elsewhere), so the same nine classifications are
            // exercised with the stdout shape this platform actually produces.
            const validRow = (pid) => (WIN
                ? JSON.stringify({
                    Name: 'node.exe', ProcessId: pid, ParentProcessId: 4242,
                    CommandLine: 'node ./memory.js mcp', StartedAt: '2026-08-02T08:00:00.0000000Z',
                })
                : `4242 Sat Aug  2 08:00:00 2026 node ./memory.js mcp`);
            const rowMissingPid = () => (WIN
                ? JSON.stringify({ Name: 'node.exe', ParentProcessId: 4242, CommandLine: 'node x', StartedAt: '2026-08-02T08:00:00Z' })
                : `notanumber Sat Aug  2 08:00:00 2026 node x`);
            const rowBadStartedAt = (pid) => (WIN
                ? JSON.stringify({ Name: 'node.exe', ProcessId: pid, ParentProcessId: 4242, CommandLine: 'node x', StartedAt: 'not-a-date' })
                : `4242 not a real lstart here node x`);

            const throws = (props) => () => { const e = new Error('injected'); Object.assign(e, props); throw e; };
            const call = (execFileSyncFn, extra = {}) =>
                lock.getProcessSnapshotResult(process.pid, { execFileSyncFn, pidAliveFn: () => true, ...extra });

            assert.strictEqual(typeof lock.getProcessSnapshotResult, 'function', 'getProcessSnapshotResult is exported');

            // 1. dead — decided before any command runs
            const dead = lock.getProcessSnapshotResult(999999, {
                pidAliveFn: () => false,
                execFileSyncFn: () => { throw new Error('the command must not run once the pid is known absent'); },
            });
            assert.strictEqual(dead.state, 'dead', 'an absent pid is dead, and no command is issued');
            assert.strictEqual(dead.detail, undefined, 'dead carries no detail — detail explains a missing answer');

            // 2. timeout — ETIMEDOUT is the ONLY criterion
            const t = call(throws({ code: 'ETIMEDOUT', status: null, signal: 'SIGTERM' }));
            assert.strictEqual(t.state, 'unavailable');
            assert.strictEqual(t.reason, 'timeout');

            // SIGTERM alone must NOT be promoted to timeout: an external kill
            // looks identical, and timeout is the one reason the gate forgives.
            const sig = call(throws({ signal: 'SIGTERM', status: null }));
            assert.strictEqual(sig.reason, 'nonzero-exit',
                'SIGTERM without ETIMEDOUT is not a timeout — forgiving it would widen the only gate exemption');

            // 3-4. spawn-error / nonzero-exit
            assert.strictEqual(call(throws({ code: 'ENOENT' })).reason, 'spawn-error');
            assert.strictEqual(call(throws({ status: 1 })).reason, 'nonzero-exit');

            // 5-7. empty-output / parse-error / no-row
            assert.strictEqual(call(() => '').reason, 'empty-output');
            assert.strictEqual(call(() => '   \n  ').reason, 'empty-output', 'whitespace-only stdout is empty');
            if (WIN) {
                assert.strictEqual(call(() => 'not json at all').reason, 'parse-error');
                assert.strictEqual(call(() => 'null').reason, 'no-row');
                assert.strictEqual(call(() => '[]').reason, 'no-row');
            }

            // 8. invalid-row — a row exists but the identity is not trustworthy.
            // It must never masquerade as alive: identity fields feed the kill
            // decision, and an invalid field is no evidence, not weak evidence.
            assert.strictEqual(call(() => rowMissingPid()).reason, 'invalid-row', 'missing/mistyped pid is invalid-row');
            assert.strictEqual(call(() => rowBadStartedAt(process.pid)).reason, 'invalid-row', 'unparseable StartedAt is invalid-row');
            if (WIN) {
                const row = (over) => JSON.stringify({
                    Name: 'node.exe', ProcessId: process.pid, ParentProcessId: 4242,
                    CommandLine: 'node x', StartedAt: '2026-08-02T08:00:00Z', ...over,
                });
                // A malformed identity row must NEVER reach alive: identity
                // fields feed the kill decision, so an invalid field is no
                // evidence rather than weak evidence.
                for (const [label, stdout] of [
                    ['different pid', row({ ProcessId: process.pid + 1 })],
                    ['pid as string', row({ ProcessId: String(process.pid) })],
                    ['ppid as string', row({ ParentProcessId: '4242' })],
                    ['negative ppid', row({ ParentProcessId: -1 })],
                    ['whitespace Name', row({ Name: '   ' })],
                    ['whitespace CommandLine', row({ CommandLine: '   ' })],
                    ['null CommandLine', row({ CommandLine: null })],
                    // A precise ProcessId query returns one object. An array
                    // with extra rows means the query did not mean what we think.
                    ['non-empty array', `[${row()},{"unexpected":"extra"}]`],
                    ['single-element array', `[${row()}]`],
                ]) {
                    assert.strictEqual(call(() => stdout).reason, 'invalid-row', `${label} must be invalid-row`);
                }
                assert.strictEqual(call(() => '[]').reason, 'no-row', 'an empty array is no-row, not invalid-row');
            }

            // 9. alive
            const ok = call(() => validRow(process.pid));
            assert.strictEqual(ok.state, 'alive', `a complete valid row is alive: ${JSON.stringify(ok)}`);
            assert.strictEqual(ok.snapshot.alive, true);
            assert.strictEqual(ok.snapshot.isNode, true);
            assert.ok(ok.snapshot.commandLine.length > 0);
            assert.ok(!Number.isNaN(Date.parse(ok.snapshot.startedAt)));
            assert.ok(Number.isInteger(ok.snapshot.ppid));
            assert.strictEqual(ok.detail, undefined, 'alive carries no detail');

            // detail is a FIXED key set — one extra key turns a contract into a
            // suggestion, so the assertion is on the exact set.
            const EXPECTED_DETAIL_KEYS = ['platform', 'elapsedMs', 'timeoutMs', 'status', 'signal',
                'errorCode', 'errorMessage', 'stdoutBytes', 'stderrBytes', 'partialStdout'];
            assert.deepStrictEqual(Object.keys(t.detail).sort(), [...EXPECTED_DETAIL_KEYS].sort(),
                'detail must carry exactly the ten frozen keys');
            assert.strictEqual(t.detail.timeoutMs, 10000, 'the production budget is unchanged at 10000ms');
            assert.strictEqual(t.detail.errorCode, 'ETIMEDOUT');
            assert.strictEqual(t.detail.signal, 'SIGTERM', 'signal is recorded but never used to infer timeout');

            // legacy snapshotFn adaptation — four frozen rules
            const legacyAlive = { alive: true, isNode: true, commandLine: 'node x', ppid: 1, ppidAlive: true, startedAt: '2026-08-02T08:00:00Z' };
            assert.strictEqual(lock.getProcessSnapshotResult(1, { snapshotFn: () => legacyAlive }).state, 'alive');
            assert.strictEqual(lock.getProcessSnapshotResult(1, { snapshotFn: () => ({ alive: false }) }).state, 'dead');
            const fromNull = lock.getProcessSnapshotResult(1, { snapshotFn: () => null });
            assert.strictEqual(fromNull.reason, 'invalid-row', 'a legacy null cannot be classified further than "unusable"');
            assert.match(String(fromNull.detail.errorMessage), /legacy snapshotFn returned null/);
            const fromThrow = lock.getProcessSnapshotResult(1, { snapshotFn: () => { throw new Error('boom'); } });
            assert.strictEqual(fromThrow.reason, 'invalid-row');
            assert.match(String(fromThrow.detail.errorMessage), /legacy snapshotFn threw/);
            assert.deepStrictEqual(Object.keys(fromNull.detail).sort(), [...EXPECTED_DETAIL_KEYS].sort(),
                'the legacy adaptation must not add a source field to detail');
            const passthrough = lock.getProcessSnapshotResult(1, { snapshotFn: () => ({ state: 'unavailable', reason: 'timeout', detail: {} }) });
            assert.strictEqual(passthrough.reason, 'timeout', 'a structured legacy return is consumed as-is');
        }
        console.log('✅ T-snap-classify passed');

        // [memory-lock-win-cim-snapshot-reliability] Phase 3A Task 2 —
        // partialStdout exists because the partial output of a timed-out query
        // is the only clue it had started answering. But that stdout can carry
        // the command line, i.e. paths and arguments, so it has to be cleaned
        // BEFORE it is truncated: truncating first would cut a secret in half
        // and let both halves escape the match.
        console.log('T-snap-detail. Diagnostic payloads are sanitized before truncation ...');
        {
            const lock = require(path.join(CLI_DIR, 'memory-index-lock.js'));
            const SENTINEL = 'secret-sentinel-do-not-leak';

            const carriers = [
                `OPENAI_API_KEY=${SENTINEL}`,
                `openai_api_key=${SENTINEL}`,
                `--token ${SENTINEL}`,
                `--key ${SENTINEL}`,
                `--password ${SENTINEL}`,
                `--secret ${SENTINEL}`,
                `Authorization: Bearer ${SENTINEL}`,
                `ghp_${SENTINEL}`,
                `sk-${SENTINEL}`,
                `SOME_TOKEN=${SENTINEL}`,
                `PASSWORD=${SENTINEL}`,
            ];
            for (const carrier of carriers) {
                const cleaned = lock.sanitizeStream(carrier);
                assert.ok(!cleaned.includes(SENTINEL),
                    `sanitizer must remove the value from ${JSON.stringify(carrier)} — got ${JSON.stringify(cleaned)}`);
                assert.ok(cleaned.includes('<redacted>'), `redaction must be visible in ${JSON.stringify(cleaned)}`);
            }
            assert.strictEqual(lock.sanitizeStream('plain output with no secrets'), 'plain output with no secrets',
                'ordinary text is untouched — over-redacting would destroy the diagnostic');

            // Order test — through the PRODUCTION entry only.
            //
            // An earlier version called truncateStream(sanitizeStream(x)), which
            // hardcodes the correct order into the test: safeStreamSample could
            // be changed to truncate first and the assertion would still pass.
            // It also put the carrier in the fully elided middle, so neither
            // order would have shown the sentinel — a false positive twice over.
            //
            // This fixture is built so the tail window starts EXACTLY at the
            // sentinel. Truncate-first therefore leaves a bare sentinel with its
            // `KEY=` carrier cut away, unmatchable by any later sanitize pass;
            // sanitize-first replaces the whole assignment before truncation.
            const key = 'OPENAI_API_KEY=';
            const suffix = 'z'.repeat(400 - Buffer.byteLength(SENTINEL, 'utf8'));
            const boundary = `${'x'.repeat(600)}${key}${SENTINEL}${suffix}`;
            const sample = lock.safeStreamSample(boundary);
            assert.ok(!sample.includes(SENTINEL),
                `safeStreamSample must sanitize BEFORE truncating — got ${JSON.stringify(sample)}`);

            // Truncation budget is in UTF-8 BYTES, not UTF-16 code units.
            const EXPECT_BYTES = 400;
            for (const [label, unit] of [['han', '汉'], ['emoji', '🙂'], ['mixed', 'a汉🙂']]) {
                const big = unit.repeat(2000);
                const out = lock.truncateStream(big);
                assert.ok(out.length < big.length, `${label}: oversized input must be truncated`);
                assert.ok(!out.includes('�'), `${label}: truncation must not split a character`);
                const [head, tail] = out.split(/…\[\d+ bytes omitted\]…/);
                assert.ok(head !== undefined && tail !== undefined, `${label}: expected an elision marker in ${JSON.stringify(out.slice(0, 80))}`);
                assert.ok(Buffer.byteLength(head, 'utf8') <= EXPECT_BYTES,
                    `${label}: head is ${Buffer.byteLength(head, 'utf8')} bytes, budget is ${EXPECT_BYTES}`);
                assert.ok(Buffer.byteLength(tail, 'utf8') <= EXPECT_BYTES,
                    `${label}: tail is ${Buffer.byteLength(tail, 'utf8')} bytes, budget is ${EXPECT_BYTES}`);
            }
            assert.strictEqual(lock.truncateStream('汉'.repeat(10)), '汉'.repeat(10),
                'input inside the budget is returned untouched');

            // errorMessage must be sanitized too. A child-process error message
            // can carry the executable and its arguments, so leaving it raw
            // would defeat the sanitizer applied to stdout.
            const msgLeak = lock.getProcessSnapshotResult(process.pid, {
                pidAliveFn: () => true,
                execFileSyncFn: () => { const e = new Error(`spawn failed --token ${SENTINEL}`); e.code = 'ENOENT'; throw e; },
            });
            assert.strictEqual(msgLeak.reason, 'spawn-error');
            assert.ok(!String(msgLeak.detail.errorMessage).includes(SENTINEL),
                `detail.errorMessage leaked the sentinel: ${msgLeak.detail.errorMessage}`);
            assert.ok(!JSON.stringify(msgLeak.detail).includes(SENTINEL), 'no detail field may carry the sentinel');

            const legacyLeak = lock.getProcessSnapshotResult(1, {
                snapshotFn: () => { throw new Error(`boom OPENAI_API_KEY=${SENTINEL}`); },
            });
            assert.strictEqual(legacyLeak.reason, 'invalid-row');
            assert.ok(!JSON.stringify(legacyLeak.detail).includes(SENTINEL),
                `the legacy throw path leaked the sentinel: ${legacyLeak.detail.errorMessage}`);

            // A throwing sanitizer must not fall back to the raw text.
            const guarded = lock.safeStreamSample(`prefix ${SENTINEL}`, () => { throw new Error('sanitizer blew up'); });
            assert.ok(!guarded.includes(SENTINEL), 'a failed sanitizer keeps nothing');
            assert.match(guarded, /^<redacted:\d+ bytes>$/, `expected a byte-count placeholder, got ${guarded}`);

            // End to end through the real classifier.
            const run = lock.getProcessSnapshotResult(process.pid, {
                pidAliveFn: () => true,
                // A carrier form, not a bare sentinel: the sanitizer redacts
                // recognized carriers, and must NOT redact arbitrary strings —
                // over-redacting would destroy the diagnostic it exists to keep.
                execFileSyncFn: () => { const e = new Error('injected'); e.code = 'ETIMEDOUT'; e.stdout = `partial output --token ${SENTINEL} trailing`; throw e; },
            });
            assert.strictEqual(run.reason, 'timeout');
            assert.ok(!String(run.detail.partialStdout).includes(SENTINEL),
                `detail.partialStdout leaked the sentinel: ${run.detail.partialStdout}`);
            assert.ok(!JSON.stringify(run.detail).includes(SENTINEL), 'no detail field may carry the sentinel');
            assert.ok(run.detail.stdoutBytes > 0, 'the byte count still reflects the real payload size');
        }
        console.log('✅ T-snap-detail passed');

        // [memory-lock-win-cim-snapshot-reliability] Phase 3A Task 4 —
        // Every unavailable reason, through BOTH entries. Testing only
        // diagnoseLockConflict proves the normal coordination flow does not
        // self-heal; it says nothing about attemptSelfHeal, which is exported
        // and can be called directly.
        console.log('T-snap-failclosed. Every unavailable reason stays fail-closed at both entries ...');
        {
            const lock = require(path.join(CLI_DIR, 'memory-index-lock.js'));
            const REASONS = ['timeout', 'spawn-error', 'nonzero-exit', 'empty-output',
                'parse-error', 'no-row', 'invalid-row'];
            const detailOf = () => ({
                platform: process.platform, elapsedMs: 1, timeoutMs: 10000, status: null, signal: null,
                errorCode: null, errorMessage: null, stdoutBytes: 0, stderrBytes: 0, partialStdout: '',
            });
            // The seam returns the structured shape directly, which the frozen
            // adaptation rules consume as-is. Injecting here is the only way to
            // manufacture every reason without a real PowerShell.
            const unavailableSeam = (reason) => ({ snapshotFn: () => ({ state: 'unavailable', reason, detail: detailOf() }) });

            const mkDir = () => fs.mkdtempSync(path.join(os.tmpdir(), 'evo-snap-fc-'));
            const writeOwner = (dir) => {
                const owner = {
                    schemaVersion: 1, leaseId: 'lease-fc', pid: 1234, ppid: 1,
                    processStartedAt: '2026-08-02T00:00:00.000Z',
                    entrypoint: path.join(WORKSPACE_ROOT, 'memory.js').replace(/\\/g, '/'),
                    mode: 'mcp', access: 'write',
                    projectRoot: WORKSPACE_ROOT.replace(/\\/g, '/'), createdAt: '2026-08-02T00:00:00.000Z',
                };
                fs.writeFileSync(path.join(dir, 'owner.json'), JSON.stringify(owner), 'utf8');
                return owner;
            };

            for (const reason of REASONS) {
                const dir = mkDir();
                try {
                    const owner = writeOwner(dir);

                    // Entry 1 — the coordination flow.
                    const diag = lock.diagnoseLockConflict(dir, {
                        projectRoot: WORKSPACE_ROOT, seams: unavailableSeam(reason),
                    });
                    assert.strictEqual(diag.verdict, 'unknown', `${reason}: verdict must be unknown, got ${diag.verdict}`);
                    assert.ok(/绝不自动终止/.test(diag.report.reason), `${reason}: the report must state it never terminates — ${diag.report.reason}`);
                    assert.ok(diag.report.reason.includes(reason), `${reason}: the reason must reach the diagnostic text — ${diag.report.reason}`);
                    assert.ok(fs.existsSync(path.join(dir, 'owner.json')), `${reason}: diagnosis must not delete the owner`);

                    // Entry 2 — the exported self-heal, called DIRECTLY with a
                    // verdict that would otherwise authorise a kill.
                    const kills = [];
                    const killFn = (pid, sig) => { kills.push([pid, sig]); };
                    const orphaned = { verdict: 'orphaned-own-mcp', owner, snapshot: null, observedLeaseId: owner.leaseId };
                    const heal = lock.attemptSelfHeal(dir, orphaned, {
                        projectRoot: WORKSPACE_ROOT,
                        seams: { ...unavailableSeam(reason), killFn },
                    });
                    assert.strictEqual(heal.healed, false, `${reason}: direct self-heal must refuse`);
                    assert.strictEqual(kills.length, 0, `${reason}: no signal may be sent — got ${JSON.stringify(kills)}`);
                    assert.ok(fs.existsSync(path.join(dir, 'owner.json')), `${reason}: self-heal must not delete the owner`);

                    // The two platforms assert DIFFERENT things and neither may
                    // claim the other's coverage. On win32 the identity recheck
                    // actually runs; elsewhere attemptSelfHeal returns at its
                    // platform gate, so the refusal is real but proves only that
                    // gate. process.platform is never faked — that would
                    // manufacture a green assertion for a path never executed.
                    if (process.platform === 'win32') {
                        assert.ok(/身份在复核时无法确认/.test(heal.reason),
                            `${reason}: on win32 the refusal must come from the identity recheck, not a platform gate — ${heal.reason}`);
                        assert.ok(heal.reason.includes(reason), `${reason}: the refusal must name the reason — ${heal.reason}`);
                    } else {
                        assert.ok(/unix 平台孤儿自愈默认关闭/.test(heal.reason),
                            `${reason}: off win32 the refusal comes from the platform gate — ${heal.reason}`);
                    }
                } finally {
                    fs.rmSync(dir, { recursive: true, force: true });
                }
            }

            // Control: the refusal above must not be an artefact of the fixture.
            // A dead holder still reaches its own distinct verdict.
            {
                const dir = mkDir();
                try {
                    writeOwner(dir);
                    const diag = lock.diagnoseLockConflict(dir, {
                        projectRoot: WORKSPACE_ROOT,
                        seams: { snapshotFn: () => ({ alive: false, isNode: null, commandLine: null, ppid: null, ppidAlive: null, startedAt: null }) },
                    });
                    assert.strictEqual(diag.verdict, 'dead-holder',
                        'positive control: a dead holder is still classified separately, so "unknown" above means something');
                } finally {
                    fs.rmSync(dir, { recursive: true, force: true });
                }
            }
        }
        console.log('✅ T-snap-failclosed passed');

        // [memory-lock-win-cim-snapshot-reliability] Phase 3A correction —
        // The production `detail` is only half of the data boundary. The other
        // half is the retained failure-site diagnostic, which prints error
        // messages, stdout/stderr samples and — through D1's `CommandLine`
        // projection — whole process command lines. T-snap-detail proves the
        // production payload is clean; it proves nothing about the line the
        // diagnostic actually emits. This test asserts the SERIALIZED text.
        console.log('T-diag-boundary. Failure-site diagnostic output carries no secrets ...');
        {
            const diagPath = path.join(WORKSPACE_ROOT, 'scripts', 'diagnostics', 'memory-lock-cim-snapshot.js');
            if (!fs.existsSync(diagPath)) {
                // The diagnostic asset ships with the create-evo-lite repository,
                // not with a scaffolded project. Absent here means there is no
                // emitter to bound — the failure-site catch above already covers
                // the missing-module case.
                console.log('   ⏭️  diagnostic asset absent in this workspace — repository-only test');
            } else {
                const diag = require(diagPath);
                const SENTINEL = 'secret-sentinel-do-not-leak';

                // One record carrying all four documented leak paths.
                const carrierErr = new Error(`Authorization: Bearer ${SENTINEL}`);
                const record = diag.buildRecord({
                    commandId: 'T_diag_boundary',
                    hostExecutable: 'powershell.exe',
                    arguments: ['-NoProfile', '-NonInteractive', '-Command'],
                    startedAt: '2026-08-03T00:00:00.000Z',
                    elapsedMs: 1234.5,
                    timeoutMs: 10000,
                    status: 0,
                    signal: null,
                    error: carrierErr,
                    stdout: `--token ${SENTINEL}`,
                    stderr: `OPENAI_API_KEY=${SENTINEL}`,
                });
                // The parse-failure message is injected through the parser seam.
                // Relying on V8's own wording would make the test depend on the
                // Node version — and V8 quotes only the first ~10 characters of
                // the input, so a real message could pass by truncation rather
                // than by redaction, which proves nothing.
                const verdict = diag.classify({ record, stdout: `PASSWORD=${SENTINEL}` }, {
                    json: true,
                    cim: true,
                    parseFn: () => { throw new Error(`PASSWORD=${SENTINEL}`); },
                });
                assert.strictEqual(verdict, diag.CLASS.JSON_PARSE_FAILURE, 'fixture must reach the parse-failure path');

                for (const field of ['errorMessage', 'stdoutSample', 'stderrSample', 'jsonParse']) {
                    const value = String(record[field]);
                    assert.ok(!value.includes(SENTINEL), `${field} leaked the sentinel: ${value}`);
                    assert.ok(value.includes('<redacted>'), `${field} must show the redaction, got ${JSON.stringify(value)}`);
                }
                assert.ok(record.stdoutBytes > 0 && record.stderrBytes > 0,
                    'byte counts must still describe the real payload size');

                const line = diag.serializeReport({
                    schema: 'memory-lock-cim-snapshot-diagnostic@1',
                    label: 'T-diag-boundary',
                    probes: [record],
                    summary: {},
                });
                assert.ok(!line.includes(SENTINEL), `the emitted line leaked the sentinel: ${line}`);
                assert.ok(line.startsWith('CIM_SNAPSHOT_DIAG='), 'the emitted line keeps its greppable prefix');
                const parsedLine = JSON.parse(line.slice('CIM_SNAPSHOT_DIAG='.length));
                assert.strictEqual(parsedLine.probes[0].classification, undefined,
                    'classify() returns the verdict; the caller attaches it');
                assert.strictEqual(parsedLine.probes[0].stdoutBytes, record.stdoutBytes,
                    'the line must stay parsable JSON with its evidence intact');

                // Negative control: serializeReport performs NO redaction of its
                // own — whole-line sanitizing would eat JSON delimiters. So the
                // four fields above are genuine carriers, and the clean line is
                // the sanitizer's doing, not the serializer's.
                const rawLine = diag.serializeReport({
                    probes: [{
                        errorMessage: carrierErr.message,
                        stdoutSample: `--token ${SENTINEL}`,
                        stderrSample: `OPENAI_API_KEY=${SENTINEL}`,
                        jsonParse: `failed: PASSWORD=${SENTINEL}`,
                    }],
                });
                assert.ok(rawLine.includes(SENTINEL),
                    'negative control failed: the serializer must not be what redacts, or this test proves nothing');

                // UTF-8 byte budget on the diagnostic path, same rule as
                // production: 400 bytes per end, never a split code point.
                const bigRecord = diag.buildRecord({
                    commandId: 'T_diag_bytes',
                    hostExecutable: 'powershell.exe',
                    arguments: [],
                    startedAt: '2026-08-03T00:00:00.000Z',
                    elapsedMs: 1,
                    timeoutMs: 10000,
                    status: 0,
                    signal: null,
                    error: null,
                    stdout: '汉'.repeat(2000),
                    stderr: '🙂'.repeat(2000),
                });
                for (const field of ['stdoutSample', 'stderrSample']) {
                    const out = String(bigRecord[field]);
                    assert.ok(!out.includes('�'), `${field}: truncation must not split a character`);
                    const [head, tail] = out.split(/…\[\d+ bytes omitted\]…/);
                    assert.ok(head !== undefined && tail !== undefined,
                        `${field}: expected an elision marker in ${JSON.stringify(out.slice(0, 60))}`);
                    assert.ok(Buffer.byteLength(head, 'utf8') <= 400,
                        `${field}: head is ${Buffer.byteLength(head, 'utf8')} bytes, budget is 400`);
                    assert.ok(Buffer.byteLength(tail, 'utf8') <= 400,
                        `${field}: tail is ${Buffer.byteLength(tail, 'utf8')} bytes, budget is 400`);
                }
                assert.strictEqual(bigRecord.stdoutBytes, Buffer.byteLength('汉'.repeat(2000), 'utf8'),
                    'the byte count describes the whole stream, not the sample');

                // Timeout classification must not be broader than the frozen
                // production contract: `timeout` is the ONE unavailable reason
                // the gate tolerates, so diagnostic evidence may not reach it by
                // an inference production would not make.
                const mkRecord = over => diag.buildRecord(Object.assign({
                    commandId: 'T_diag_class',
                    hostExecutable: 'powershell.exe',
                    arguments: [],
                    startedAt: '2026-08-03T00:00:00.000Z',
                    elapsedMs: 500,
                    timeoutMs: 10000,
                    status: 0,
                    signal: null,
                    error: null,
                    stdout: 'ok',
                    stderr: '',
                }, over));

                const etimedout = () => { const e = new Error('spawnSync ETIMEDOUT'); e.code = 'ETIMEDOUT'; return e; };

                const timedOut = mkRecord({ error: etimedout(), status: null, signal: 'SIGTERM', elapsedMs: 10123, stdout: '' });
                assert.strictEqual(diag.classify({ record: timedOut, stdout: '' }, { cim: true }), diag.CLASS.CIM_QUERY_TIMEOUT,
                    'ETIMEDOUT is still a timeout');
                const timedOutPlain = mkRecord({ error: etimedout(), status: null, signal: 'SIGTERM', elapsedMs: 10123, stdout: '' });
                assert.strictEqual(diag.classify({ record: timedOutPlain, stdout: '' }, {}), diag.CLASS.POWERSHELL_SPAWN_TIMEOUT,
                    'ETIMEDOUT without CIM is still a host timeout');

                // An external SIGTERM inside the budget is a kill, not a timeout.
                const killed = mkRecord({ status: null, signal: 'SIGTERM', elapsedMs: 500, stdout: '' });
                assert.strictEqual(diag.classify({ record: killed, stdout: '' }, { cim: true }), diag.CLASS.POWERSHELL_NONZERO_EXIT,
                    'SIGTERM without ETIMEDOUT must not be classified as a timeout');
                assert.strictEqual(killed.boundaryExceeded, false, 'a kill inside the budget did not reach the boundary');

                // Reaching the wall-clock budget without ETIMEDOUT is evidence,
                // never a verdict.
                const slow = mkRecord({ elapsedMs: 10123, status: 0, stdout: 'ok' });
                assert.strictEqual(diag.classify({ record: slow, stdout: 'ok' }, {}), diag.CLASS.OK,
                    'a slow but successful command is OK, not a timeout');
                assert.strictEqual(slow.boundaryExceeded, true, 'the boundary crossing is still recorded as evidence');

                // Partial stdout is evidence about a timeout, not a different
                // terminal state — the label stays the production one.
                const partial = mkRecord({ error: etimedout(), status: null, signal: 'SIGTERM', elapsedMs: 10123, stdout: 'half a row' });
                const partialVerdict = diag.classify({ record: partial, stdout: 'half a row' }, { cim: true });
                assert.strictEqual(partialVerdict, diag.CLASS.CIM_QUERY_TIMEOUT,
                    'partial stdout must not change the timeout classification');
                assert.notStrictEqual(partialVerdict, diag.CLASS.POWERSHELL_PARTIAL_STDOUT_TIMEOUT,
                    'the partial-stdout class is retained vocabulary only, never emitted');
                assert.strictEqual(partial.partialStdout, true, 'partial stdout is recorded as evidence');
            }
        }
        console.log('✅ T-diag-boundary passed');

        console.log('T-lock-orphan-refusal-matrix. Testing four-gate refusal — 11 cases, never killable ...');
        {
            const lock = require(path.join(CLI_DIR, 'memory-index-lock.js'));
            const HERE = WORKSPACE_ROOT;
            const mkLockDir = () => fs.mkdtempSync(path.join(os.tmpdir(), 'evo-lock-refuse-'));
            const writeRaw = (dir, obj) => fs.writeFileSync(
                path.join(dir, 'owner.json'),
                typeof obj === 'string' ? obj : JSON.stringify(obj, null, 2), 'utf8');
            const baseOwner = (over = {}) => ({
                schemaVersion: 1, leaseId: 'lease-refuse', pid: 999999, ppid: 1,
                processStartedAt: '2026-07-23T00:00:00.000Z',
                entrypoint: path.join(os.tmpdir(), 'fake-entry', 'memory.js'),
                mode: 'mcp', access: 'write', projectRoot: HERE,
                createdAt: '2026-07-23T00:00:00.000Z', ...over,
            });
            // 拒杀三件套:verdict 绝非 orphaned / 诊断信息在场 / owner 未被删改 / 目标进程存活
            const ownerBytes = dir => fs.readFileSync(path.join(dir, 'owner.json'), 'utf8');
            const assertRefusal = (dir, before, diag, holderPid) => {
                assert.notStrictEqual(diag.verdict, 'orphaned-own-mcp', 'must never be killable');
                assert.notStrictEqual(diag.verdict, 'dead-holder', 'must not treat as cleanable stale owner');
                assert.ok(diag.report && diag.report.reason, 'report carries a reason');
                assert.ok(diag.report.lockPath.includes('LOCK'), 'report names the LOCK path');
                assert.ok(diag.report.enumerate.includes('memory'), 'report carries enumeration command');
                assert.strictEqual(ownerBytes(dir), before, 'owner.json untouched');
                if (holderPid) assert.ok(lock.pidAlive(holderPid), 'target process must survive');
            };
            // 长驻 holder:脚本文件名与 argv 可控(伪装 memory.js mcp / stats 等形态)
            const spawnHolder = (scriptName, args) => {
                const hd = fs.mkdtempSync(path.join(os.tmpdir(), 'evo-lock-holder-'));
                const scriptPath = path.join(hd, scriptName);
                fs.writeFileSync(scriptPath, 'setInterval(() => {}, 1000);\n', 'utf8');
                const child = childProcess.spawn(process.execPath, [scriptPath, ...args], { stdio: 'ignore' });
                return { child, scriptPath };
            };
            // 防 flake:等待 OS 进程表可见(快照含 startedAt)再继续
            const waitForSnapshot = pid => {
                const deadline = Date.now() + 5000;
                let snap = lock.getProcessSnapshot(pid);
                while ((!snap || !snap.startedAt) && Date.now() < deadline) {
                    lock.sleepSync(100);
                    snap = lock.getProcessSnapshot(pid);
                }
                assert.ok(snap && snap.startedAt, `snapshot for pid ${pid} must become available`);
                return snap;
            };
            const holders = [];
            try {
                // 1. pid 存活但非 memory.js 进程(闸②:entrypoint 不匹配)
                {
                    const dir = mkLockDir();
                    const { child, scriptPath } = spawnHolder('plain.js', []);
                    holders.push(child);
                    writeRaw(dir, baseOwner({ pid: child.pid, entrypoint: scriptPath }));
                    const before = ownerBytes(dir);
                    const diag = lock.diagnoseLockConflict(dir, { projectRoot: HERE });
                    assert.strictEqual(diag.verdict, 'unknown', 'case 1: non-memory.js holder');
                    assertRefusal(dir, before, diag, child.pid);
                }
                // 2. projectRoot 不一致(闸④)—— holder 是 memory.js mcp 形态,身份闸通过
                {
                    const dir = mkLockDir();
                    const { child, scriptPath } = spawnHolder('memory.js', ['mcp']);
                    holders.push(child);
                    const snap = waitForSnapshot(child.pid);
                    writeRaw(dir, baseOwner({
                        pid: child.pid, entrypoint: scriptPath,
                        processStartedAt: snap.startedAt,
                        projectRoot: path.join(os.tmpdir(), 'some-other-repo'),
                    }));
                    const before = ownerBytes(dir);
                    const diag = lock.diagnoseLockConflict(dir, { projectRoot: HERE });
                    assert.strictEqual(diag.verdict, 'live-foreign', 'case 2: foreign project');
                    assertRefusal(dir, before, diag, child.pid);
                }
                // 3. ppid 仍存活(闸③)—— holder 由测试进程直接 spawn
                {
                    const dir = mkLockDir();
                    const { child, scriptPath } = spawnHolder('memory.js', ['mcp']);
                    holders.push(child);
                    const snap = waitForSnapshot(child.pid);
                    writeRaw(dir, baseOwner({ pid: child.pid, entrypoint: scriptPath, processStartedAt: snap.startedAt }));
                    const before = ownerBytes(dir);
                    const diag = lock.diagnoseLockConflict(dir, { projectRoot: HERE });
                    assert.strictEqual(diag.verdict, 'live-foreign', 'case 3: parent still alive');
                    assert.ok(String(diag.report.reason).includes('不会自动终止'), 'live-foreign states no auto-kill');
                    assertRefusal(dir, before, diag, child.pid);
                }
                // 4. 快照不可得(seam 返回 null)
                {
                    const dir = mkLockDir();
                    writeRaw(dir, baseOwner());
                    const before = ownerBytes(dir);
                    const diag = lock.diagnoseLockConflict(dir, { projectRoot: HERE, seams: { snapshotFn: () => null } });
                    assert.strictEqual(diag.verdict, 'unknown', 'case 4: snapshot unavailable');
                    assertRefusal(dir, before, diag, null);
                }
                // 5. owner 损坏(半截 JSON)
                {
                    const dir = mkLockDir();
                    writeRaw(dir, '{ "schemaVersion": 1, "leaseId": "trunc');
                    const before = ownerBytes(dir);
                    const diag = lock.diagnoseLockConflict(dir, { projectRoot: HERE });
                    assert.strictEqual(diag.verdict, 'unknown', 'case 5: corrupt owner');
                    assert.ok(String(diag.report.reason).includes('持有者未登记'), 'corrupt reads as unregistered holder');
                    assertRefusal(dir, before, diag, null);
                }
                // 6. PID 复用(闸②:startedAt 与快照不符)
                {
                    const dir = mkLockDir();
                    const { child, scriptPath } = spawnHolder('memory.js', ['mcp']);
                    holders.push(child);
                    writeRaw(dir, baseOwner({ pid: child.pid, entrypoint: scriptPath, processStartedAt: '2020-01-01T00:00:00.000Z' }));
                    const before = ownerBytes(dir);
                    const diag = lock.diagnoseLockConflict(dir, { projectRoot: HERE });
                    assert.strictEqual(diag.verdict, 'unknown', 'case 6: startedAt mismatch = PID reuse');
                    assertRefusal(dir, before, diag, child.pid);
                }
                // 7. 权限不足(seam 抛 access-denied)
                {
                    const dir = mkLockDir();
                    writeRaw(dir, baseOwner());
                    const before = ownerBytes(dir);
                    const diag = lock.diagnoseLockConflict(dir, { projectRoot: HERE, seams: { snapshotFn: () => { throw new Error('access denied'); } } });
                    assert.strictEqual(diag.verdict, 'unknown', 'case 7: access denied');
                    assertRefusal(dir, before, diag, null);
                }
                // 8/9/10. identity-critical 缺失或 schemaVersion 未知(R1 P0-2)
                {
                    const mutations = [
                        ['missing processStartedAt', o => { delete o.processStartedAt; }],
                        ['missing leaseId', o => { delete o.leaseId; }],
                        ['schemaVersion 99', o => { o.schemaVersion = 99; }],
                    ];
                    for (const [label, mutate] of mutations) {
                        const dir = mkLockDir();
                        const o = baseOwner();
                        mutate(o);
                        writeRaw(dir, o);
                        const before = ownerBytes(dir);
                        const diag = lock.diagnoseLockConflict(dir, { projectRoot: HERE });
                        assert.strictEqual(diag.verdict, 'unknown', `case 8-10 (${label}): invalid owner is report-only`);
                        assertRefusal(dir, before, diag, null);
                    }
                }
                // 11. 实际命令非 mcp + owner.mode 伪造 'mcp'(R1 P1)
                {
                    const dir = mkLockDir();
                    const { child, scriptPath } = spawnHolder('memory.js', ['stats']);
                    holders.push(child);
                    const snap = waitForSnapshot(child.pid);
                    writeRaw(dir, baseOwner({ pid: child.pid, entrypoint: scriptPath, processStartedAt: snap.startedAt, mode: 'mcp' }));
                    const before = ownerBytes(dir);
                    const diag = lock.diagnoseLockConflict(dir, { projectRoot: HERE });
                    assert.strictEqual(diag.verdict, 'unknown', 'case 11: stats holder with forged mode must never be killable');
                    assertRefusal(dir, before, diag, child.pid);
                }
                // 正向对照:闸① ESRCH → dead-holder + observedLeaseId(观察字段;接管路径不预删 owner)
                {
                    const dir = mkLockDir();
                    const dead = childProcess.spawnSync(process.execPath, ['-e', 'process.exit(0)']);
                    writeRaw(dir, baseOwner({ pid: dead.pid }));
                    const diag = lock.diagnoseLockConflict(dir, { projectRoot: HERE });
                    assert.strictEqual(diag.verdict, 'dead-holder');
                    assert.strictEqual(diag.observedLeaseId, 'lease-refuse', 'observed leaseId captured for diagnostics');
                }
            } finally {
                for (const h of holders) { try { h.kill(); } catch (_) {} }
            }
        }
        console.log('✅ T-lock-orphan-refusal-matrix passed (11/11 refusals + dead-holder probe)');

        console.log('T-lock-coordination. Testing passthrough / live-foreign / orphan self-heal (zvec cases skip if absent) ...');
        {
            const lock = require(path.join(CLI_DIR, 'memory-index-lock.js'));
            const HERE = WORKSPACE_ROOT;

            // 非锁错误零干预:原样 rethrow,不 backoff、不诊断、不产 owner
            {
                const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'evo-lock-passthru-'));
                const boom = new Error('schema mismatch: not a lock problem');
                let threw = null;
                try {
                    lock.openWithCoordination(() => { throw boom; }, dir, { projectRoot: HERE });
                } catch (err) {
                    threw = err;
                }
                assert.strictEqual(threw, boom, 'non-lock error rethrown untouched (same object)');
                assert.ok(!fs.existsSync(path.join(dir, 'owner.json')), 'no owner written on failure');
            }

            // P0-2:open 成功但 owner 发布失败 → 立即 closeSync 回收,不留无 sidecar 的锁
            {
                const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'evo-lock-publish-'));
                let closed = 0;
                const fakeCol = { closeSync() { closed++; } };
                const boom = new Error('rename denied');
                let threw = null;
                try {
                    lock.openWithCoordination(() => fakeCol, dir, {
                        projectRoot: HERE,
                        seams: { writeOwnerFn: () => { throw boom; } },
                    });
                } catch (err) { threw = err; }
                assert.strictEqual(threw, boom, 'publish failure rethrown untouched');
                assert.strictEqual(closed, 1, 'collection closed exactly once on publish failure');
                assert.ok(!fs.existsSync(path.join(dir, 'owner.json')), 'no owner left behind');
                const ok = lock.openWithCoordination(() => fakeCol, dir, { projectRoot: HERE });
                assert.ok(ok.leaseId, 'second opener publishes normally');
                lock.clearOwner(dir, ok.leaseId); // 测试清理
            }

            // P0-1(TOCTOU):dead-holder 接管不预删 stale owner;重试瞬间 B 抢先
            // 接管 → A 失败后绝不删除 B 的 owner,重新诊断一轮后抛富化错误
            {
                const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'evo-lock-toctou-'));
                const dead = childProcess.spawnSync(process.execPath, ['-e', 'process.exit(0)']);
                const staleOwner = {
                    schemaVersion: 1, leaseId: 'stale-dead-lease', pid: dead.pid, ppid: 1,
                    processStartedAt: '2026-07-23T00:00:00.000Z',
                    entrypoint: path.join(os.tmpdir(), 'fake-entry', 'memory.js'),
                    mode: 'mcp', access: 'write', projectRoot: HERE,
                    createdAt: '2026-07-23T00:00:00.000Z',
                };
                fs.writeFileSync(path.join(dir, 'owner.json'), JSON.stringify(staleOwner), 'utf8');
                const lockErr = new Error("Can't lock read-write collection: LOCK");
                let calls = 0;
                let leaseB = null;
                let threw = null;
                try {
                    lock.openWithCoordination(() => {
                        calls++;
                        if (calls === 5) {
                            // dead-holder 分支的最终重试瞬间:B 抢先接管
                            leaseB = lock.writeOwner(dir, { mode: 'cli', projectRoot: HERE });
                        }
                        throw lockErr;
                    }, dir, { projectRoot: HERE, seams: { isLockErrorFn: () => true } });
                } catch (err) { threw = err; }
                assert.ok(threw && threw.code === 'EVO_ZVEC_LOCKED', 'still-locked takeover throws enriched error');
                assert.ok(leaseB, 'race actually injected at the takeover retry');
                assert.strictEqual(lock.readOwner(dir).owner.leaseId, leaseB, 'B owner survives — A never deletes on failure');
                lock.clearOwner(dir, leaseB); // 测试清理
            }

            // P0-1:接管成功 = 持锁期间 writeOwner 原子覆盖 stale,全程无 unlink
            {
                const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'evo-lock-takeover-'));
                const dead = childProcess.spawnSync(process.execPath, ['-e', 'process.exit(0)']);
                const staleOwner = {
                    schemaVersion: 1, leaseId: 'stale-dead-lease', pid: dead.pid, ppid: 1,
                    processStartedAt: '2026-07-23T00:00:00.000Z',
                    entrypoint: path.join(os.tmpdir(), 'fake-entry', 'memory.js'),
                    mode: 'mcp', access: 'write', projectRoot: HERE,
                    createdAt: '2026-07-23T00:00:00.000Z',
                };
                fs.writeFileSync(path.join(dir, 'owner.json'), JSON.stringify(staleOwner), 'utf8');
                const lockErr = new Error("Can't lock read-write collection: LOCK");
                let calls = 0;
                const fakeCol = { closeSync() {} };
                const opened = lock.openWithCoordination(() => {
                    calls++;
                    if (calls <= 4) throw lockErr; // backoff 期间全部失败
                    return fakeCol;                // dead-holder 最终重试成功
                }, dir, { projectRoot: HERE, seams: { isLockErrorFn: () => true } });
                assert.strictEqual(opened.result, fakeCol);
                const rec = lock.readOwner(dir);
                assert.strictEqual(rec.state, 'valid');
                assert.strictEqual(rec.owner.pid, process.pid, 'stale owner atomically replaced by takeover writeOwner');
                lock.clearOwner(dir, opened.leaseId); // 测试清理
            }

            let zvecAvailable = true;
            try { require.resolve('@zvec/zvec'); } catch (_) { zvecAvailable = false; }
            if (!zvecAvailable) {
                console.log('   ⏭️ zvec-dependent coordination cases skipped — @zvec/zvec not installed');
            } else {
                const zvec = require('@zvec/zvec');
                const lockModulePath = path.join(CLI_DIR, 'memory-index-lock.js');
                const mkCollection = () => {
                    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'evo-lock-coord-'));
                    const colPath = path.join(dir, 'collection');
                    const schema = new zvec.ZVecCollectionSchema({
                        name: 'locktest',
                        fields: [{ name: 'content', dataType: zvec.ZVecDataType.STRING }],
                    });
                    const col = zvec.ZVecCreateAndOpen(colPath, schema);
                    col.closeSync();
                    return { dir, colPath };
                };
                // holder 脚本落在 os.tmpdir(),而 Node 的模块解析以【脚本所在目录】
                // 向上走,cwd 不参与。因此裸 require('@zvec/zvec') 在 CI runner 上必然
                // MODULE_NOT_FOUND —— 本地之所以能过,是碰巧命中了开发机上一个游离的
                // 用户级 node_modules(实测解析到 C:\Users\<user>\node_modules),
                // 与本仓安装无关。父进程已用绝对路径传 lock 模块,zvec 照同一方式传,
                // 顺带保证 holder 与父进程加载的是【同一份】zvec,不会跨版本错配。
                const zvecEntry = require.resolve('@zvec/zvec');
                const HOLDER_SRC = [
                    "'use strict';",
                    "const fs = require('fs');",
                    "const path = require('path');",
                    "const zvec = require(process.argv[6]);",
                    "const lock = require(process.argv[4]);",
                    "const dir = process.argv[3];",
                    "const col = zvec.ZVecOpen(path.join(dir, 'collection'));",
                    "global.__evoLockHolderCollection = col; // 防 V8 GC 回收无引用局部量 → 原生 finalizer 提前释放锁(zombie-MCP gotcha 复现)",
                    "lock.writeOwner(dir, { mode: 'mcp', projectRoot: process.argv[5] });",
                    "fs.writeFileSync(path.join(dir, 'holder-ready.txt'), String(process.pid), 'utf8');",
                    "setInterval(() => {}, 1000);",
                ].join('\n');
                const writeHolderScript = () => {
                    const hd = fs.mkdtempSync(path.join(os.tmpdir(), 'evo-lock-hscript-'));
                    const scriptPath = path.join(hd, 'memory.js'); // 文件名必须是 memory.js(闸②)
                    fs.writeFileSync(scriptPath, HOLDER_SRC, 'utf8');
                    return scriptPath;
                };
                const waitForFile = (file, timeoutMs) => {
                    const deadline = Date.now() + timeoutMs;
                    while (Date.now() < deadline) {
                        if (fs.existsSync(file)) return true;
                        lock.sleepSync(50);
                    }
                    return fs.existsSync(file);
                };

                // live-foreign:holder 由本测试进程 spawn(ppid 活)→ 富化错误,不杀
                {
                    const { dir, colPath } = mkCollection();
                    const scriptPath = writeHolderScript();
                    const holder = childProcess.spawn(process.execPath, [scriptPath, 'mcp', dir, lockModulePath, HERE, zvecEntry], {
                        stdio: ['ignore', 'ignore', 'pipe'], cwd: WORKSPACE_ROOT, env: { ...process.env },
                    });
                    // 可观察性:holder 以 stdio:'ignore' 起时,任何子进程异常都被吞掉,
                    // 父测试只能报一句误导性的 'holder acquired the lock'。把 spawn 错误、
                    // 退出码/信号与 stderr 收集起来,超时时一并放进断言。
                    let holderStderr = '';
                    let holderExit = null;
                    let holderSpawnError = null;
                    holder.stderr.on('data', d => { holderStderr += String(d); });
                    holder.on('error', e => { holderSpawnError = e; });
                    holder.on('exit', (code, signal) => { holderExit = { code, signal }; });
                    try {
                        assert.ok(waitForFile(path.join(dir, 'holder-ready.txt'), 8000),
                            'holder never signalled readiness — it did not acquire the lock. '
                            + `spawnError=${holderSpawnError ? holderSpawnError.message : 'none'} `
                            + `exit=${holderExit ? JSON.stringify(holderExit) : 'still running'} `
                            + `stderr=${JSON.stringify(holderStderr.slice(0, 600)) || '(empty)'}`);
                        const holderOwnerBytes = fs.readFileSync(path.join(dir, 'owner.json'), 'utf8');
                        const killSpy = [];
                        let threw = null;
                        try {
                            lock.openWithCoordination(() => zvec.ZVecOpen(colPath), dir, {
                                projectRoot: HERE,
                                seams: { killFn: (pid, sig) => { killSpy.push([pid, sig]); } },
                            });
                        } catch (err) {
                            threw = err;
                        }
                        assert.ok(threw, 'conflict must throw');
                        assert.strictEqual(threw.code, 'EVO_ZVEC_LOCKED');
                        assert.strictEqual(threw.verdict, 'live-foreign');
                        assert.ok(threw.message.includes(String(holder.pid)), 'error names holder pid');
                        assert.ok(threw.message.includes('不会自动终止'), 'error states no auto-kill');
                        assert.ok(threw.message.includes('Get-CimInstance') || threw.message.includes('ps -eo'), 'error carries enumeration command');
                        assert.ok(threw.cause, 'original zvec error preserved as cause');
                        assert.strictEqual(killSpy.length, 0, 'killFn never invoked on live-foreign');
                        assert.ok(lock.pidAlive(holder.pid), 'holder survives');
                        assert.strictEqual(fs.readFileSync(path.join(dir, 'owner.json'), 'utf8'), holderOwnerBytes, 'holder owner not overwritten');
                    } finally {
                        try { holder.kill(); } catch (_) {}
                    }
                }

                // orphan self-heal(原事故最小复刻):中间 spawner detached 拉起孙子后退出
                // plan R1 P1-2:自愈限定 win32 —— unix 孤儿被 init 接管(ppid→1),仅诊断
                if (process.platform !== 'win32') {
                    console.log('   ⏭️ orphan self-heal case skipped — 自愈限定 win32,unix 为 report-only 策略');
                } else {
                    const { dir, colPath } = mkCollection();
                    const scriptPath = writeHolderScript();
                    const SPAWNER_SRC = [
                        "'use strict';",
                        "const { spawn } = require('child_process');",
                        "const fs = require('fs');",
                        "const path = require('path');",
                        "const [holderScript, dir, lockPath, projectRoot, zvecEntry] = process.argv.slice(2);",
                        "const child = spawn(process.execPath, [holderScript, 'mcp', dir, lockPath, projectRoot, zvecEntry], { detached: true, stdio: 'ignore', env: process.env, cwd: process.cwd() });",
                        "child.unref();",
                        "const ready = path.join(dir, 'holder-ready.txt');",
                        "(function wait() { if (fs.existsSync(ready)) process.exit(0); setTimeout(wait, 50); })();",
                    ].join('\n');
                    const spawnerPath = path.join(path.dirname(scriptPath), 'spawner.js');
                    fs.writeFileSync(spawnerPath, SPAWNER_SRC, 'utf8');
                    childProcess.execFileSync(process.execPath, [spawnerPath, scriptPath, dir, lockModulePath, HERE, zvecEntry], {
                        cwd: WORKSPACE_ROOT, env: { ...process.env }, timeout: 15000,
                    });
                    const orphanPid = Number(fs.readFileSync(path.join(dir, 'holder-ready.txt'), 'utf8'));
                    assert.ok(lock.pidAlive(orphanPid), 'orphan holder alive before coordination');
                    let opened = null;
                    try {
                        opened = lock.openWithCoordination(() => zvec.ZVecOpen(colPath), dir, { projectRoot: HERE });
                        assert.ok(opened && opened.result, 'self-heal recovered the lock');
                        assert.ok(typeof opened.leaseId === 'string' && opened.leaseId.length > 0);
                        assert.strictEqual(lock.pidAlive(orphanPid), false, 'orphan terminated');
                        const rec = lock.readOwner(dir);
                        assert.strictEqual(rec.state, 'valid');
                        assert.strictEqual(rec.owner.pid, process.pid, 'owner now belongs to us');
                    } finally {
                        if (opened && opened.result) { try { opened.result.closeSync(); } catch (_) {} }
                        if (opened) lock.clearOwner(dir, opened.leaseId);
                        try { process.kill(orphanPid); } catch (_) {} // 自愈失败时兜底,不留僵尸
                    }
                }
            }
        }
        console.log('✅ T-lock-coordination passed');

        console.log('T-lock-ephemeral. Testing ephemeral lock tenure matrix (skips if @zvec/zvec absent) ...');
        {
            let zvecAvailable = true;
            try { require.resolve('@zvec/zvec'); } catch (_) { zvecAvailable = false; }
            if (!zvecAvailable) {
                console.log('   ⏭️ skipped — @zvec/zvec not installed (optional dependency)');
            } else {
                const prevEphemeral = process.env.EVO_LITE_INDEX_EPHEMERAL;
                const runtime = createTempRuntimeRoot('lock-ephemeral');
                await bootstrapRuntime(runtime.runtimeRoot);
                const lock = require(path.join(CLI_DIR, 'memory-index-lock.js'));
                try {
                    process.env.EVO_LITE_INDEX_EPHEMERAL = '1';
                    resetCliModuleCache();
                    const { ZvecMemoryIndex } = require(path.join(CLI_DIR, 'memory-index-zvec.js'));
                    const a = new ZvecMemoryIndex();

                    // success → close:公共契约是"第二实例可立即打开"
                    a.upsert({ content: 'ephemeral tenure probe recall', namespace: 'prose', timestamp: '2026-07-23T00:00:00Z' });
                    assert.strictEqual(a._col, null, 'aux white-box: collection released after op');
                    const b = new ZvecMemoryIndex();
                    b.initialize(); // a 若仍持锁,这里会 Can't lock
                    b.close();
                    assert.strictEqual(lock.readOwner(a._dir).state, 'missing', 'owner cleared after finalize');

                    // throw → close:异常路径 finally 释放
                    let threw = false;
                    try {
                        a._withCollection(() => { throw new Error('op failure'); });
                    } catch (_) { threw = true; }
                    assert.ok(threw, 'op error propagates');
                    assert.strictEqual(a._col, null, 'released after throwing op');
                    const c = new ZvecMemoryIndex();
                    c.initialize();
                    c.close();

                    // nested success:inner 不提前 close,outer 归零才 finalize
                    a._withCollection(() => {
                        const hits = a.searchText('ephemeral', { topK: 3 });
                        assert.ok(Array.isArray(hits), 'inner op works');
                        assert.ok(a._col !== null, 'inner op must not close while outer active');
                    });
                    assert.strictEqual(a._col, null, 'outer exit finalizes');

                    // nested throw:不破坏 depth,outer finally 正常释放
                    try {
                        a._withCollection(() => {
                            a._withCollection(() => { throw new Error('inner failure'); });
                        });
                    } catch (_) {}
                    assert.strictEqual(a._depth, 0, 'depth restored after nested throw');
                    assert.strictEqual(a._col, null, 'outer finally released despite inner throw');

                    // default mode:未设环境变量 → op 后集合仍开(现行为不变)
                    delete process.env.EVO_LITE_INDEX_EPHEMERAL;
                    resetCliModuleCache();
                    const { ZvecMemoryIndex: DefaultZvec } = require(path.join(CLI_DIR, 'memory-index-zvec.js'));
                    const d = new DefaultZvec();
                    d.upsert({ content: 'default tenure probe', namespace: 'prose', timestamp: '2026-07-23T00:01:00Z' });
                    assert.ok(d._col !== null, 'default mode keeps collection open after op');
                    d.close();
                    assert.strictEqual(lock.readOwner(d._dir).state, 'missing', 'close clears owner in default mode too');
                } finally {
                    if (prevEphemeral === undefined) delete process.env.EVO_LITE_INDEX_EPHEMERAL;
                    else process.env.EVO_LITE_INDEX_EPHEMERAL = prevEphemeral;
                    resetCliModuleCache();
                }
            }
        }
        console.log('✅ T-lock-ephemeral passed');

        console.log('T-zvec06-readonly-matrix. Characterizing real cross-process readOnly concurrency (skips if @zvec/zvec absent) ...');
        {
            let zvecAvailable = true;
            try { require.resolve('@zvec/zvec'); } catch (_) { zvecAvailable = false; }
            if (!zvecAvailable) {
                console.log('   ⏭️ skipped — @zvec/zvec not installed');
            } else {
                const zvec = require('@zvec/zvec');
                const lock = require(path.join(CLI_DIR, 'memory-index-lock.js'));

                // 设计附录 A 的七项判定矩阵。必须用真实临时 collection + 独立 OS 进程:
                // 函数 arity、源码 grep、同进程双实例都测不出 OS 级文件锁行为。
                // API 是否接受 { readOnly: true } 并不能说明它是否具有实际共享读语义 ——
                // 静默接受正是本矩阵要抓的东西,所以判定只能来自跨进程可观察的并发结果。
                // Phase 0B 实测:0.5.0 与 0.6.0 【均】具有真实共享读语义,两版逐行一致。
                // holder 落在 os.tmpdir(),Node 的模块解析以【脚本所在目录】向上走,cwd 不参与。
                // 裸 require('@zvec/zvec') 在 CI runner 上必然 MODULE_NOT_FOUND;开发机上则会
                // 命中一个游离的用户级 node_modules,于是 holder 加载的 zvec 与父进程【不是同一份】
                // —— Phase 0B 的 0.6 只读矩阵就是这样变成 0.5-holder × 0.6-prober 的混版测量。
                // 传绝对路径同时解决两件事:CI 上能解析,且两端保证同一 binding。
                const zvecEntry = require.resolve('@zvec/zvec');
                const HOLDER_SRC = [
                    "'use strict';",
                    "const fs = require('fs');",
                    "const [, , colPath, mode, readyFile, releaseFile, zvecEntry] = process.argv;",
                    "const zvec = require(zvecEntry);",
                    "let col;",
                    "try { col = mode === 'ro' ? zvec.ZVecOpen(colPath, { readOnly: true }) : zvec.ZVecOpen(colPath); }",
                    "catch (e) {",
                    "    fs.writeFileSync(readyFile, JSON.stringify({ ok: false, name: e.name, code: e.code, message: String(e.message) }));",
                    "    process.exit(0);",
                    "}",
                    "global.__evoHoldCollection = col;   // 防 V8 GC 回收无引用局部量 → 原生 finalizer 提前释放锁",
                    "fs.writeFileSync(readyFile, JSON.stringify({ ok: true, pid: process.pid }));",
                    "const timer = setInterval(() => {",
                    "    if (!fs.existsSync(releaseFile)) return;",
                    "    clearInterval(timer);",
                    "    try { col.closeSync(); } catch (_) {}",
                    "    process.exit(0);",
                    "}, 40);",
                ].join('\n');

                const matrixDir = fs.mkdtempSync(path.join(os.tmpdir(), 'evo-zvec06-'));
                const holderScript = path.join(matrixDir, 'holder.js');
                fs.writeFileSync(holderScript, HOLDER_SRC, 'utf8');
                const colPath = path.join(matrixDir, 'collection');
                zvec.ZVecCreateAndOpen(colPath, new zvec.ZVecCollectionSchema({
                    name: 'zvec06matrix',
                    fields: [{ name: 'content', dataType: zvec.ZVecDataType.STRING }],
                })).closeSync();

                const waitFor = (file, timeoutMs) => {
                    const deadline = Date.now() + timeoutMs;
                    while (Date.now() < deadline) {
                        if (fs.existsSync(file)) return true;
                        lock.sleepSync(40);
                    }
                    return fs.existsSync(file);
                };
                const holders = [];
                const startHolder = (tag, mode) => {
                    const readyFile = path.join(matrixDir, `${tag}-ready.json`);
                    const releaseFile = path.join(matrixDir, `${tag}-release`);
                    const proc = childProcess.spawn(process.execPath, [holderScript, colPath, mode, readyFile, releaseFile, zvecEntry],
                        { stdio: ['ignore', 'ignore', 'pipe'], cwd: WORKSPACE_ROOT, env: { ...process.env } });
                    // 一个死掉的 holder 必须自报死因。stdio:'ignore' 会把子进程异常吞掉,只留下
                    // 一句 'never reported back' —— 那正是 release-gate 曾经红了八天却指错方向的原因。
                    let stderr = '';
                    let exited = null;
                    let spawnError = null;
                    proc.stderr.on('data', d => { stderr += String(d); });
                    proc.on('error', e => { spawnError = e; });
                    proc.on('exit', (code, signal) => { exited = { code, signal }; });
                    holders.push({ tag, proc, releaseFile });
                    assert.ok(waitFor(readyFile, 15000),
                        `${tag} holder never reported back. `
                        + `spawnError=${spawnError ? spawnError.message : 'none'} `
                        + `exit=${exited ? JSON.stringify(exited) : 'still running'} `
                        + `stderr=${JSON.stringify(stderr.slice(0, 600)) || '(empty)'}`);
                    return JSON.parse(fs.readFileSync(readyFile, 'utf8'));
                };
                const releaseHolder = tag => {
                    const h = holders.find(x => x.tag === tag);
                    if (!h) return;
                    fs.writeFileSync(h.releaseFile, 'go', 'utf8');
                    const deadline = Date.now() + 15000;
                    while (Date.now() < deadline && h.proc.exitCode === null && h.proc.signalCode === null) lock.sleepSync(40);
                };
                // 探测方也是独立进程(本测试进程 ≠ holder 进程),是真实跨进程冲突。
                const probe = opts => {
                    let handle = null;
                    try {
                        handle = opts ? zvec.ZVecOpen(colPath, opts) : zvec.ZVecOpen(colPath);
                        try { handle.closeSync(); } catch (_) {}
                        return { ok: true };
                    } catch (e) {
                        return {
                            ok: false, name: e.name, code: e.code, message: String(e.message),
                            isZVecError: zvec.isZVecError(e),
                            matchesCanLock: /can't lock/i.test(String(e.message || '')),
                            hasCause: e.cause !== undefined,
                            // [zvec-win-unicode-containment] Task 5 — production now
                            // injects the native predicate (memory-index-lock no longer
                            // requires @zvec/zvec itself). Both forms are observed here:
                            // the injected one is what production runs, the pure one is
                            // the fallback mirroring upstream's own isZVecError contract.
                            // Requiring them to agree turns an upstream definition change
                            // into a red test instead of a silent downgrade to bare rethrow.
                            isLockError_injected: lock.isLockError(e, zvec.isZVecError),
                            isLockError_pure: lock.isLockError(e),
                        };
                    }
                };
                const observed = {};
                const report = () => {
                    console.log('   --- zvec readOnly concurrency contract (observed) ---');
                    for (const [k, v] of Object.entries(observed)) {
                        console.log(`   ${k.padEnd(28)} ${v.ok ? 'OK' : 'BLOCKED ' + v.name + '/' + v.code}`);
                    }
                };

                try {
                    // 0. 负控:两个可写打开【必须】冲突。没有这条,「两个 reader 共存」
                    //    可能只是夹具根本检测不出冲突,而不是 readOnly 真的生效。
                    startHolder('control', 'rw');
                    observed['0 control writer×writer'] = probe(null);
                    assert.ok(!observed['0 control writer×writer'].ok,
                        'negative control failed: two writable opens did NOT conflict, so this fixture cannot detect lock conflicts at all and every other row below is meaningless');
                    releaseHolder('control');

                    // 1. reader A 以 readOnly:true 打开
                    observed['1 readerA(ro)'] = startHolder('readerA', 'ro');
                    assert.ok(observed['1 readerA(ro)'].ok,
                        `reader A must open read-only: ${JSON.stringify(observed['1 readerA(ro)'])}`);

                    // 2. reader B 与 A 并发打开 —— 跨版本兼容性与读写锁行为合同
                    observed['2 readerB(ro) w/ A'] = probe({ readOnly: true });
                    // 3. reader 存活时 writer 的实际结果(不预设方向,只要求结论自洽)
                    observed['3 writer w/ readers'] = probe(null);
                    // 4. 所有 reader 关闭后 writer 是否立即恢复
                    releaseHolder('readerA');
                    observed['4 writer after readers'] = probe(null);
                    // 5. writer 存活时 reader 的实际结果
                    startHolder('writer', 'rw');
                    observed['5 reader w/ writer'] = probe({ readOnly: true });
                    // 6. writer 关闭后 reader 是否恢复
                    releaseHolder('writer');
                    observed['6 reader after writer'] = probe({ readOnly: true });
                    report();

                    // --- 不变量:与 0.5/0.6 无关,任何版本都必须成立 ---
                    assert.ok(observed['4 writer after readers'].ok,
                        `writer must recover once every reader closed: ${JSON.stringify(observed['4 writer after readers'])}`);
                    assert.ok(observed['6 reader after writer'].ok,
                        `reader must recover once the writer closed: ${JSON.stringify(observed['6 reader after writer'])}`);
                    // 7. 锁冲突的真实错误形状 —— 附录 A 第 8 项:检测锚定在 0.5 的
                    //    /can't lock/i 文案上,文案一变所有冲突会静默降级为裸 rethrow。
                    const conflicts = Object.entries(observed).filter(([, v]) => !v.ok);
                    for (const [caseName, v] of conflicts) {
                        assert.ok(v.isZVecError, `${caseName}: a lock conflict must still be a zvec error — ${JSON.stringify(v)}`);
                        assert.ok(v.isLockError_injected,
                            `${caseName}: isLockError() with the injected native predicate — the form production uses — must still classify this conflict, otherwise every lock diagnostic silently degrades to a bare rethrow — ${JSON.stringify(v)}`);
                        assert.strictEqual(v.isLockError_pure, v.isLockError_injected,
                            `${caseName}: the native-free fallback disagrees with the injected predicate, so upstream's isZVecError contract has moved and the mirror in memory-index-lock is stale — ${JSON.stringify(v)}`);
                    }
                    if (conflicts.length) {
                        const [, sample] = conflicts[0];
                        console.log(`   lock error shape: name=${sample.name} code=${sample.code} `
                            + `isZVecError=${sample.isZVecError} matchesCanLock=${sample.matchesCanLock} hasCause=${sample.hasCause}`);
                    }

                    // --- 跨版本行为合同:多进程并发只读 ---
                    // 不是 0.5 RED / 0.6 GREEN 的升级判据 —— 两版都满足。它锁的是
                    // 「这条语义在升级前后都不许消失」,回归时才会变红。
                    assert.ok(observed['2 readerB(ro) w/ A'].ok,
                        `two concurrent read-only readers must coexist — a behavioural contract that held on both 0.5.0 and 0.6.0 and must not regress. Observed: ${JSON.stringify(observed['2 readerB(ro) w/ A'])}`);
                } finally {
                    for (const h of holders) {
                        try { fs.writeFileSync(h.releaseFile, 'go', 'utf8'); } catch (_) {}
                        try { h.proc.kill(); } catch (_) {}
                    }
                    try { fs.rmSync(matrixDir, { recursive: true, force: true }); } catch (_) {}
                }
                console.log('✅ T-zvec06-readonly-matrix passed');
            }
        }

        console.log('T-zvec-namespace-isolation. Testing that an empty scope never leaks other namespaces (skips if @zvec/zvec absent) ...');
        {
            let zvecAvailable = true;
            try { require.resolve('@zvec/zvec'); } catch (_) { zvecAvailable = false; }
            if (!zvecAvailable) {
                console.log('   ⏭️ skipped — @zvec/zvec not installed');
            } else {
                // 数据隔离合同。zvec 0.5.0 无法区分「没有 candidate 限制」与「过滤器已执行
                // 但命中 0 条」,于是把空 candidate 列表当成「不过滤」—— recall 一个【空】
                // namespace 会返回其他 namespace 的文档。实测 0.5.0 泄漏 / 0.6.0 返回 []。
                // 这是 Evo-Lite 自己的 prose/code/symbol 边界,不是上游 release note 的转述,
                // 所以断言必须走真实的 ZvecMemoryIndex.searchText,不能只测引擎原语。
                const prevRoot = process.env.EVO_LITE_ROOT;
                const prevDb = process.env.EVO_LITE_DB_PATH;
                const nsDir = fs.mkdtempSync(path.join(os.tmpdir(), 'evo-ns-isolation-'));
                try {
                    resetCliModuleCache();
                    process.env.EVO_LITE_ROOT = nsDir;
                    process.env.EVO_LITE_DB_PATH = path.join(nsDir, 'memory.db');
                    const { ZvecMemoryIndex } = require(path.join(CLI_DIR, 'memory-index-zvec.js'));
                    const idx = new ZvecMemoryIndex();
                    idx.initialize();
                    try {
                        const ts = '2026-07-31T00:00:00.000Z';
                        idx.upsert({ content: 'zqxjkvbrw 只存在于 prose 的独特令牌', namespace: 'prose', timestamp: ts });
                        idx.upsert({ content: 'zqxjkvbrw shared token in the symbol namespace', namespace: 'symbol', timestamp: ts });
                        // namespace 'code' 故意留空 —— 这正是触发条件。

                        // 控制项先行:过滤器命中时必须真的返回结果。若这两条失败,
                        // 下面的空结果可能只是「查询本身就查不到」,断言就没有意义。
                        const all = idx.searchText('zqxjkvbrw', { scope: 'all', topK: 10 });
                        assert.strictEqual(all.length, 2,
                            `control failed: the token must be findable without a scope filter, else the isolation assertion below is vacuous. Got ${JSON.stringify(all.map(r => r.namespace))}`);
                        const prose = idx.searchText('zqxjkvbrw', { scope: 'prose', topK: 10 });
                        assert.deepStrictEqual(prose.map(r => r.namespace), ['prose'],
                            `control failed: a scope filter that DOES match must still return its own namespace. Got ${JSON.stringify(prose.map(r => r.namespace))}`);

                        // 合同本体:目标 namespace 为空 → 必须严格为空,不得回退成「不过滤」。
                        const empty = idx.searchText('zqxjkvbrw', { scope: 'code', topK: 10 });
                        assert.deepStrictEqual(empty.map(r => r.namespace), [],
                            `namespace isolation breach: recall(scope='code') returned documents from ${JSON.stringify(empty.map(r => r.namespace))} while the code namespace is empty. A zero-match scalar filter must NOT degrade into "no filter" — that hands the agent other namespaces' memory under a scope it explicitly narrowed.`);
                        const unknown = idx.searchText('zqxjkvbrw', { scope: 'no-such-namespace', topK: 10 });
                        assert.deepStrictEqual(unknown.map(r => r.namespace), [],
                            `namespace isolation breach: an unknown scope returned ${JSON.stringify(unknown.map(r => r.namespace))} instead of nothing.`);
                    } finally {
                        try { idx.close(); } catch (_) {}
                    }
                } finally {
                    if (prevRoot === undefined) delete process.env.EVO_LITE_ROOT; else process.env.EVO_LITE_ROOT = prevRoot;
                    if (prevDb === undefined) delete process.env.EVO_LITE_DB_PATH; else process.env.EVO_LITE_DB_PATH = prevDb;
                    resetCliModuleCache();
                    try { fs.rmSync(nsDir, { recursive: true, force: true }); } catch (_) {}
                }
                console.log('✅ T-zvec-namespace-isolation passed');
            }
        }

        console.log('T-zvec-reopen-visibility. Testing that un-optimized writes survive a reopen (skips if @zvec/zvec absent) ...');
        {
            let zvecAvailable = true;
            try { require.resolve('@zvec/zvec'); } catch (_) { zvecAvailable = false; }
            if (!zvecAvailable) {
                console.log('   ⏭️ skipped — @zvec/zvec not installed');
            } else {
                // ZvecMemoryIndex._finalizeSync() 吞掉 optimizeSync() 的异常
                // (`try { ... } catch (_) {}`),进程被杀时也根本走不到 optimize。
                // 于是「已写入但未 optimize」是一个合法且可达的落盘状态。zvec 0.5.0
                // 重开后丢失该 writing segment 的 FTS 统计 → 这些 archive 静默检索不到。
                // 这里用 _dirty=false 精确复刻「optimize 没有发生」的那条路径。
                const prevRoot = process.env.EVO_LITE_ROOT;
                const prevDb = process.env.EVO_LITE_DB_PATH;
                const rvDir = fs.mkdtempSync(path.join(os.tmpdir(), 'evo-reopen-vis-'));
                try {
                    resetCliModuleCache();
                    process.env.EVO_LITE_ROOT = rvDir;
                    process.env.EVO_LITE_DB_PATH = path.join(rvDir, 'memory.db');
                    const { ZvecMemoryIndex } = require(path.join(CLI_DIR, 'memory-index-zvec.js'));
                    const ts = '2026-07-31T00:00:00.000Z';

                    const first = new ZvecMemoryIndex();
                    first.initialize();
                    for (let i = 0; i < 3; i++) {
                        first.upsert({ content: `sealed rvprobe archive ${i}`, namespace: 'prose', timestamp: ts });
                    }
                    first.close();                       // dirty → optimize 正常发生,成为已封存 segment

                    const second = new ZvecMemoryIndex();
                    second.initialize();
                    for (let i = 0; i < 3; i++) {
                        second.upsert({ content: `unoptimized rvprobe archive ${i}`, namespace: 'prose', timestamp: ts });
                    }
                    const before = second.searchText('rvprobe', { scope: 'all', topK: 20 });
                    assert.strictEqual(before.length, 6,
                        `control failed: all 6 archives must be visible to the writer that just wrote them, else the post-reopen assertion is vacuous. Got ${before.length}`);
                    // ⚠ fault injection seam(白盒),不是业务用法:直接压掉 _dirty 让
                    // _finalizeSync() 跳过 optimizeSync(),精确复刻「optimize 没有发生」
                    // 的那条落盘路径 —— 异常被 catch(_) 吞掉,或进程在 finalize 前被杀。
                    // 若将来 _dirty 更名或语义变化,这里要跟着改,否则测试会静默失效。
                    second._dirty = false;
                    second.close();

                    const third = new ZvecMemoryIndex();
                    third.initialize();
                    try {
                        const after = third.searchText('rvprobe', { scope: 'all', topK: 20 });
                        assert.strictEqual(after.length, 6,
                            `archive loss after reopen: only ${after.length}/6 archives are findable once the collection is reopened without an intervening optimize. Writes that were never optimized must stay searchable — otherwise a swallowed optimizeSync() error or a killed process silently makes committed archives unrecallable, with no error anywhere.`);
                    } finally {
                        try { third.close(); } catch (_) {}
                    }
                } finally {
                    if (prevRoot === undefined) delete process.env.EVO_LITE_ROOT; else process.env.EVO_LITE_ROOT = prevRoot;
                    if (prevDb === undefined) delete process.env.EVO_LITE_DB_PATH; else process.env.EVO_LITE_DB_PATH = prevDb;
                    resetCliModuleCache();
                    try { fs.rmSync(rvDir, { recursive: true, force: true }); } catch (_) {}
                }
                console.log('✅ T-zvec-reopen-visibility passed');
            }
        }

        console.log('T-mcp-stdin-exit. Testing MCP stdin-EOF lifecycle (A) + shutdown cleanup of a held lock (B) (skips if @zvec/zvec absent) ...');
        {
            let zvecAvailable = true;
            try { require.resolve('@zvec/zvec'); } catch (_) { zvecAvailable = false; }
            if (!zvecAvailable) {
                console.log('   ⏭️ skipped — @zvec/zvec not installed (optional dependency)');
            } else {
                const lock = require(path.join(CLI_DIR, 'memory-index-lock.js'));
                // 逐行解析 stdout JSON-RPC,等待指定 id 的 response(plan R1 P1-1:
                // 不用固定 sleep 猜时序)
                const attachRpcReader = child => {
                    const seen = new Map();
                    let buf = '';
                    child.stdout.on('data', chunk => {
                        buf += chunk.toString();
                        const lines = buf.split('\n');
                        buf = lines.pop();
                        for (const line of lines) {
                            if (!line.trim()) continue;
                            try {
                                const parsed = JSON.parse(line);
                                if (parsed.id != null) seen.set(parsed.id, parsed);
                            } catch (_) {}
                        }
                    });
                    return async (id, timeoutMs) => {
                        const deadline = Date.now() + timeoutMs;
                        while (Date.now() < deadline) {
                            if (seen.has(id)) return seen.get(id);
                            await new Promise(r => setTimeout(r, 50));
                        }
                        return seen.get(id) || null;
                    };
                };
                const rpc = (id, method, params) => JSON.stringify({ jsonrpc: '2.0', id, method, params }) + '\n';

                // A. 真实 entrypoint 生命周期:initialize 有响应后 stdin EOF → 自行 exit 0
                {
                    const runtime = createTempRuntimeRoot('mcp-stdin-a');
                    await bootstrapRuntime(runtime.runtimeRoot);
                    const memJs = path.join(CLI_DIR, 'memory.js');
                    const child = childProcess.spawn(process.execPath, [memJs, 'mcp'], {
                        cwd: runtime.workspaceRoot,
                        env: {
                            ...process.env,
                            EVO_LITE_ROOT: runtime.runtimeRoot,
                            EVO_LITE_SKIP_GIT_GUARD: '1',
                            EVO_LITE_MEMORY_ENGINE: 'zvec', // 显式固定,防前序测试遗留 env 干扰
                        },
                        stdio: ['pipe', 'pipe', 'pipe'],
                    });
                    const exited = new Promise(resolve => child.on('exit', code => resolve(code)));
                    let killedByTimeout = false;
                    const failsafe = setTimeout(() => { killedByTimeout = true; try { child.kill(); } catch (_) {} }, 20000);
                    try {
                        const waitFor = attachRpcReader(child);
                        child.stdin.write(rpc(0, 'initialize', {
                            protocolVersion: '2024-11-05', capabilities: {},
                            clientInfo: { name: 't-lock-stdin-a', version: '1' },
                        }));
                        assert.ok(await waitFor(0, 10000), 'initialize response received before EOF');
                        child.stdin.end(); // 宿主死亡的最小模拟:stdin EOF
                        const code = await exited;
                        clearTimeout(failsafe);
                        assert.ok(!killedByTimeout, 'server exits on its own after stdin EOF (no zombie)');
                        assert.strictEqual(code, 0, `exit code 0 expected, got ${code}`);
                    } finally {
                        clearTimeout(failsafe);
                        try { child.kill(); } catch (_) {}
                    }
                }

                // B. shutdown cleanup(plan R1 P1-1):server 启动前索引已以非
                //    ephemeral 状态真实持锁 + owner 在场 → stdin EOF → shutdown
                //    必须 close 活动索引、清 owner、释放 native 锁。
                //    (ephemeral 路径下 recall 返回时锁本已释放,只有本场景能
                //    证明 shutdown 会收尾活动 collection。)
                {
                    const runtime = createTempRuntimeRoot('mcp-stdin-b');
                    // This sub-case needs a REAL zvec owner, so it needs a
                    // collection path containment will actually admit.
                    const anchor = createContainedZvecRoot('mcp-stdin-b');
                    if (!anchor.safe) {
                        anchor.cleanup();
                        throw new Error(`cannot run the live-zvec lock case: workspace anchor is not in the supported profile (${anchor.containment.reason}). Move the checkout to an ASCII path.`);
                    }
                    // bootstrapRuntime writes extraEnv straight into process.env
                    // and never restores it, so this must be undone by hand —
                    // otherwise later tests inherit a db path pointing at the
                    // anchor this block is about to delete.
                    const prevDbPath = process.env.EVO_LITE_DB_PATH;
                    const anchored = await bootstrapRuntime(runtime.runtimeRoot, { EVO_LITE_DB_PATH: anchor.dbPath });
                    const wrapDir = fs.mkdtempSync(path.join(os.tmpdir(), 'evo-lock-mcpwrap-'));
                    const readyFile = path.join(wrapDir, 'wrapper-ready.txt');
                    const WRAPPER_SRC = [
                        "'use strict';",
                        `process.env.EVO_LITE_ROOT = ${JSON.stringify(runtime.runtimeRoot)};`,
                        // Supported-profile anchor: containment must admit this
                        // path, otherwise the wrapper degrades to SQLite and no
                        // zvec owner is ever written.
                        `process.env.EVO_LITE_DB_PATH = ${JSON.stringify(anchor.dbPath)};`,
                        "process.env.EVO_LITE_SKIP_GIT_GUARD = '1';",
                        "process.env.EVO_LITE_MEMORY_ENGINE = 'zvec';",
                        "delete process.env.EVO_LITE_INDEX_EPHEMERAL; // 防外部 shell 环境污染(plan R2 执行提示)",
                        "delete process.env.EVO_LITE_PROCESS_MODE;",
                        `const { getMemoryIndex } = require(${JSON.stringify(path.join(CLI_DIR, 'memory-index.js'))});`,
                        "const idx = getMemoryIndex();",
                        "idx.initialize(); // 此刻 EVO_LITE_INDEX_EPHEMERAL 未设 → 真实持锁 + owner 在场",
                        `require('fs').writeFileSync(${JSON.stringify(readyFile)}, String(process.pid), 'utf8');`,
                        `const { runMcpServer } = require(${JSON.stringify(path.join(CLI_DIR, 'mcp-server.js'))});`,
                        "runMcpServer();",
                    ].join('\n');
                    const wrapperPath = path.join(wrapDir, 'mcp-wrapper.js');
                    fs.writeFileSync(wrapperPath, WRAPPER_SRC, 'utf8');
                    const child = childProcess.spawn(process.execPath, [wrapperPath], {
                        cwd: runtime.workspaceRoot,
                        env: { ...process.env },
                        stdio: ['pipe', 'pipe', 'pipe'],
                    });
                    const exited = new Promise(resolve => child.on('exit', code => resolve(code)));
                    let killedByTimeout = false;
                    const failsafe = setTimeout(() => { killedByTimeout = true; try { child.kill(); } catch (_) {} }, 20000);
                    try {
                        const waitFor = attachRpcReader(child);
                        const deadline = Date.now() + 10000;
                        while (!fs.existsSync(readyFile) && Date.now() < deadline) {
                            await new Promise(r => setTimeout(r, 50));
                        }
                        assert.ok(fs.existsSync(readyFile), 'wrapper initialized a lock-holding index');
                        const zvecDir = anchor.paths.rootPath;
                        const held = lock.readOwner(zvecDir);
                        assert.strictEqual(held.state, 'valid', 'owner present while index holds the lock');
                        assert.strictEqual(held.owner.pid, Number(fs.readFileSync(readyFile, 'utf8')), 'owner is the wrapper process');
                        assert.strictEqual(held.owner.mode, 'cli', 'wrapper index opened before runMcpServer declares mcp mode');
                        child.stdin.write(rpc(0, 'initialize', {
                            protocolVersion: '2024-11-05', capabilities: {},
                            clientInfo: { name: 't-lock-stdin-b', version: '1' },
                        }));
                        assert.ok(await waitFor(0, 10000), 'server responsive before EOF');
                        child.stdin.end();
                        const code = await exited;
                        clearTimeout(failsafe);
                        assert.ok(!killedByTimeout, 'wrapper exits on its own (shutdown closed the active index)');
                        assert.strictEqual(code, 0, `exit code 0 expected, got ${code}`);
                        assert.strictEqual(lock.readOwner(zvecDir).state, 'missing', 'shutdown cleared the active owner');
                        // 不变量 6:native 锁确实释放 —— 新 writer 立即 initialize 成功。
                        // 绑定到同一个受控 anchor,否则这里会去开另一个 collection,
                        // 证明不了刚才那把锁被释放。
                        resetCliModuleCache();
                        const { ZvecMemoryIndex } = require(path.join(CLI_DIR, 'memory-index-zvec.js'));
                        const writer = new ZvecMemoryIndex({ paths: anchor.paths });
                        assert.strictEqual(writer._colPath, anchor.paths.collectionPath, 'the new writer targets the collection the server just held');
                        writer.initialize(); // 死服务器若仍持锁,这里 Can't lock
                        writer.close();
                    } finally {
                        clearTimeout(failsafe);
                        try { child.kill(); } catch (_) {}
                        // The parent still holds a better-sqlite3 handle on the
                        // anchored db; on Windows an open handle turns the
                        // cleanup unlink into EBUSY.
                        try { anchored.db.closeDb(); } catch (_) {}
                        if (prevDbPath === undefined) delete process.env.EVO_LITE_DB_PATH;
                        else process.env.EVO_LITE_DB_PATH = prevDbPath;
                        anchor.cleanup();
                    }
                }
            }
        }
        console.log('✅ T-mcp-stdin-exit passed (A: lifecycle, B: shutdown cleanup)');

        console.log('T-SPACE-ENGINE. Testing verify memory-space line reports the ACTIVE index engine (skips if @zvec/zvec absent) ...');
